import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import SessionService from '../../services/sessionService';
import { portalHomeForRole } from '../../utils/authorization';

/**
 * This page is the redirect target for Google OAuth.
 * The backend sends: /oauth-callback?token=...&user=...
 * We pick those up, store them, and redirect to the right dashboard.
 */
const OAuthCallback = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const { completeOAuthLogin } = useAuth();
    const [error, setError] = useState('');

    useEffect(() => {
        const params = new URLSearchParams(location.search);
        const token = params.get('token');
        const userStr = params.get('user');
        const oauthError = params.get('error');

        if (oauthError || !token || !userStr) {
            setError('Social login failed. Please try again.');
            setTimeout(() => navigate('/login'), 2500);
            return;
        }

        try {
            const user = JSON.parse(decodeURIComponent(userStr));

            // Correctly initialize a fully valid session with an ID and timestamps
            SessionService.startSession(user, token);

            // Let AuthContext know we're logged in
            completeOAuthLogin(user, token);

            // Defer navigation slightly so AuthContext has time to propagate the new state
            // to all consumers (like ProtectedRoute), circumventing false access rejections.
            setTimeout(() => {
                navigate(portalHomeForRole(user.role), { replace: true });
            }, 300);
        } catch (e) {
            setError('Could not parse login data. Please try again.');
            setTimeout(() => navigate('/login'), 2500);
        }
    }, [location, navigate]);

    return (
        <div className="flex min-h-screen flex-col items-center justify-center bg-stone-50 font-sans dark:bg-stone-950">
            {error ? (
                <div style={{ color: '#dc2626', fontSize: 16 }}>
                    ⚠️ {error}
                </div>
            ) : (
                <>
                    <div style={{
                        width: 48, height: 48, border: '4px solid #d97706',
                        borderTopColor: 'transparent', borderRadius: '50%',
                        animation: 'spin 0.8s linear infinite'
                    }} />
                    <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
                    <p className="mt-5 text-[15px] text-secondary">
                        Completing sign-in…
                    </p>
                </>
            )}
        </div>
    );
};

export default OAuthCallback;
