const getStaffMenu = (user) => {
  if (isCareProfessional(user)) {
    const config = getStaffWorkspaceConfig(effectiveStaffType(user));
    const menu = [
      { path: '/admin/dashboard', label: 'My Work', icon: Activity },
      { path: '/admin/bookings', label: config.bookingsTitle, icon: Calendar },
      { path: '/profile', label: 'My Professional Profile', icon: User }
    ];
    const additional = [];
    const can = (resource, action) => hasUiActionPermission(user, resource, action, false);

    // Professional defaults such as inventory.vaccine and services.view do not
    // represent permission to administer the store catalog. Only an explicit
    // general module grant adds one of these management destinations.
    if (can('inventory', 'view') || can('inventory', 'manage')) additional.push({ path: '/admin/inventory', label: 'Inventory', icon: Package });
    if (can('procurement', 'view') || can('procurement', 'manage')) additional.push({ path: '/admin/purchase-orders', label: 'Procurement', icon: Truck });
    if (can('finance', 'view') || can('finance', 'manage')) additional.push({ path: '/admin/finance', label: 'Finance', icon: DollarSign });
    if (can('dss', 'view') || can('dss', 'manage')) additional.push({ path: '/admin/insights', label: 'Insights', icon: Brain });
    if (additional.length) menu.push({ label: 'Additional Access', icon: ShieldCheck, children: additional });
    return menu;
  }

  const menu = [
    { path: '/admin/dashboard', label: 'Dashboard', icon: Activity },
  ];
  if (hasUiPermission(user, 'dss')) menu.push({ path: '/admin/insights', label: 'Business Insights', icon: Brain });

  const catalogChildren = [];
  if (hasUiPermission(user, 'inventory') || hasUiPermission(user, 'pets')) catalogChildren.push({ path: '/admin/pets', label: 'Pets', icon: Heart });
  if (hasUiPermission(user, 'inventory') || hasUiPermission(user, 'products')) catalogChildren.push({ path: '/admin/products', label: 'Products', icon: Package });
  if (hasUiPermission(user, 'services')) catalogChildren.push({ path: '/admin/services', label: 'Services', icon: Calendar });
  if (catalogChildren.length > 0) menu.push({ label: 'Products & Services', icon: Package, children: catalogChildren });

  const opsChildren = [];
  if (hasUiPermission(user, 'orders')) opsChildren.push({ path: '/admin/orders', label: 'Orders', icon: ShoppingCart });
  if (hasUiPermission(user, 'bookings')) opsChildren.push({ path: '/admin/bookings', label: 'Bookings', icon: Calendar });
  if (hasUiPermission(user, 'customers')) opsChildren.push({ path: '/admin/customers', label: 'Customers', icon: Users });
  if (hasUiPermission(user, 'admin_chat')) opsChildren.push({ path: '/admin/chat', label: 'Chat', icon: MessageSquare });
  if (hasUiPermission(user, 'reviews')) opsChildren.push({ path: '/admin/reviews', label: 'Reviews', icon: Star });
  if (opsChildren.length > 0) menu.push({ label: 'Operations', icon: ShoppingBag, children: opsChildren });

  const supplyChildren = [];
  if (['inventory_staff', 'procurement_officer'].includes(effectiveStaffType(user))) {
    supplyChildren.push({ path: '/admin/purchase-orders', label: 'Purchase Orders', icon: Truck });
  }
  if (supplyChildren.length > 0) menu.push({ label: 'Supply Chain', icon: Truck, children: supplyChildren });

  const financeChildren = [];
  if (effectiveStaffType(user) === 'finance_staff') financeChildren.push({ path: '/admin/finance', label: 'Finance Records', icon: DollarSign });
  if (hasUiPermission(user, 'vouchers')) financeChildren.push({ path: '/admin/vouchers', label: 'Vouchers', icon: Ticket });
  if (financeChildren.length > 0) menu.push({ label: 'Finance', icon: DollarSign, children: financeChildren });

  const mgmtChildren = [];
  if (hasUiPermission(user, 'analytics')) mgmtChildren.push({ path: '/admin/stats', label: 'Stats', icon: TrendingUp });
  if (hasUiPermission(user, 'staff')) mgmtChildren.push({ path: '/admin/staff', label: 'Staff', icon: Users });
  if (['admin', 'store_owner', 'super_admin', 'platform_admin'].includes(user?.role)) {
    mgmtChildren.push({ path: '/admin/roles', label: 'Role Management', icon: ShieldCheck });
  }
  if (mgmtChildren.length > 0) menu.push({ label: 'Management', icon: Settings, children: mgmtChildren });

  return menu;
};

// ═══════════════════════════════════════════════════════════════
// NAV ITEM SUB-COMPONENTS
// ═══════════════════════════════════════════════════════════════

const NavLink = ({ item, isActive, collapsed, onClick }) => {
  const Icon = item.icon;
  return (
    <Link
      to={item.path}
      onClick={onClick}
      title={collapsed ? item.label : undefined}
      className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all duration-300 relative group/link ${isActive
          ? 'bg-primary text-white shadow-strong'
          : 'text-slate-500 hover:bg-primary/5 hover:text-primary'
        } ${collapsed ? 'justify-center px-3' : ''}`}
    >
      <Icon className={`h-5 w-5 shrink-0 transition-transform duration-300 ${isActive ? 'scale-110' : 'group-hover/link:scale-110'}`} />
      {!collapsed && (
        <span className="text-xs font-bold tracking-tight truncate">{item.label}</span>
      )}
      {collapsed && (
        <div className="absolute left-full ml-4 px-3 py-2 bg-neutral-900 text-white text-[10px] font-black uppercase tracking-widest rounded-xl opacity-0 group-hover/link:opacity-100 pointer-events-none transition-all duration-300 whitespace-nowrap z-[200] shadow-premium translate-x-2 group-hover/link:translate-x-0">
          {item.label}
        </div>
      )}
    </Link>
  );
};

const NavGroup = ({ group, expanded, onToggle, isActive, collapsed, onNavigate }) => {
  const Icon = group.icon;
  const hasActiveChild = isActive;

  if (collapsed) {
    return (
      <div className="relative group/flyout">
        <button
          title={group.label}
          className={`flex items-center justify-center w-full px-4 py-3 rounded-2xl transition-all duration-300 ${hasActiveChild
              ? 'bg-primary/10 text-primary'
              : 'text-slate-400 hover:bg-neutral-50 hover:text-slate-600'
            }`}
        >
          <Icon className="h-5 w-5 shrink-0" />
        </button>
        <div className="absolute left-full top-0 ml-4 bg-white border border-slate-100 rounded-[2rem] shadow-premium p-3 min-w-[220px] opacity-0 invisible group-hover/flyout:opacity-100 group-hover/flyout:visible transition-all duration-300 z-[200] translate-x-4 group-hover/flyout:translate-x-0">
          <div className="px-5 py-2 text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-2">{group.label}</div>
          <div className="space-y-1">
            {group.children.map(child => (
              <NavLink key={child.path} item={child} isActive={window.location.pathname === child.path} collapsed={false} onClick={onNavigate} />
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-1">
      <button
        onClick={onToggle}
        className={`flex items-center gap-3 w-full px-4 py-3 rounded-2xl transition-all duration-300 group/btn ${hasActiveChild
            ? 'bg-primary/5 text-primary'
            : 'text-slate-500 hover:bg-neutral-50 hover:text-neutral-900'
          }`}
      >
        <Icon className="h-5 w-5 shrink-0 transition-transform group-hover/btn:scale-110" />
        <span className="text-xs font-bold tracking-tight flex-1 text-left truncate">{group.label}</span>
        <ChevronDown className={`h-4 w-4 shrink-0 transition-transform duration-500 ${expanded ? 'rotate-180' : ''} text-slate-300`} />
      </button>
      <div className={`overflow-hidden transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] ${expanded ? 'max-h-[600px] opacity-100 mt-2' : 'max-h-0 opacity-0'}`}>
        <div className="pl-6 space-y-1 border-l-2 border-slate-50 ml-7 py-2">
          {group.children.map(child => {
            const ChildIcon = child.icon;
            const childActive = window.location.pathname === child.path;
            return (
              <Link
                key={child.path}
                to={child.path}
                onClick={onNavigate}
                className={`flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all duration-300 ${childActive
                    ? 'bg-primary text-white shadow-medium scale-[1.02]'
                    : 'text-slate-400 hover:text-primary hover:bg-primary/5'
                  }`}
              >
                <ChildIcon className="h-4 w-4 shrink-0" />
                <span className="text-[11px] font-bold tracking-tight truncate">{child.label}</span>
              </Link>
            );
          })}
        </div>
      </div>
    </div>
  );
};

